const themeSelect = document.querySelector("#theme-select");
const iconGrid = document.querySelector("#icon-grid");
const status = document.querySelector("#gallery-status");
const count = document.querySelector("#icon-count");
const search = document.querySelector("#icon-search");
const macroCode = document.querySelector("#macro-code");
const curlExamples = document.querySelector("#curl-examples");
const copyMacro = document.querySelector("#copy-macro");
const copyStatus = document.querySelector("#copy-status");
const iconDialog = document.querySelector("#icon-dialog");
const dialogTitle = document.querySelector("#icon-dialog-title");
const dialogImage = document.querySelector("#icon-dialog-image");
const dialogSlug = document.querySelector("#icon-dialog-slug");
const dialogFolderLink = document.querySelector("#icon-dialog-folder");
const folderLinkIcon = document.querySelector("#folder-link-icon");
const systemTheme = window.matchMedia("(prefers-color-scheme: dark)");
const siteBase = new URL("./", window.location.href);
let icons = [];
let macroSource = "";

function setTheme(choice) {
  const resolved = choice === "system" ? (systemTheme.matches ? "dark" : "light") : choice;
  document.documentElement.dataset.cdsTheme = `magnetic-blue-${resolved}`;
  document.documentElement.style.colorScheme = resolved;
  themeSelect.value = choice;
}

const savedTheme = localStorage.getItem("roomos-icon-gallery-theme");
themeSelect.value = ["system", "light", "dark"].includes(savedTheme) ? savedTheme : "system";
setTheme(themeSelect.value);
themeSelect.addEventListener("change", () => {
  localStorage.setItem("roomos-icon-gallery-theme", themeSelect.value);
  setTheme(themeSelect.value);
});
systemTheme.addEventListener("change", () => {
  if (themeSelect.value === "system") setTheme("system");
});

function makeElement(tag, className, text) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (text !== undefined) element.textContent = text;
  return element;
}

function getGitHubRepository() {
  const host = window.location.hostname;
  const pathParts = siteBase.pathname.split("/").filter(Boolean);
  if (!host.endsWith(".github.io")) return null;

  const owner = host.slice(0, -".github.io".length);
  const isUserSite = pathParts.length === 0 || pathParts[0].toLowerCase() === `${owner.toLowerCase()}.github.io`;
  const repository = isUserSite ? `${owner}.github.io` : pathParts[0];
  return {
    url: `https://github.com/${owner}/${repository}`,
    siteUrl: siteBase.href,
    fileBase: `https://github.com/${owner}/${repository}/blob/main/`,
    rawBase: `https://raw.githubusercontent.com/${owner}/${repository}/main/`,
  };
}

const repository = getGitHubRepository();
if (repository) {
  for (const link of document.querySelectorAll("[data-repository-link]")) {
    link.href = repository.url;
  }
  for (const link of document.querySelectorAll("[data-repository-file]")) {
    link.href = `${repository.fileBase}${link.dataset.repositoryFile}`;
  }
}

function renderCurlExamples(rawBase) {
  const lines = [
    "# Fetch the manifest",
    "curl \\",
    "  -L --fail --show-error \\",
    `  '${rawBase}manifest.json' \\`,
    "  -o manifest.json",
    "",
    "# Replace this example path with an svg or png path from the manifest",
    "curl \\",
    "  -L --fail --show-error \\",
    `  '${rawBase}icons/camera-off/camera-off.svg' \\`,
    "  -o camera-off.svg",
  ];

  curlExamples.replaceChildren();
  for (const [index, line] of lines.entries()) {
    if (line.startsWith("#")) {
      const comment = makeElement("span", "syntax-comment", line);
      curlExamples.append(comment);
    } else {
      const tokens = line.match(/'[^']*'|--?[a-zA-Z-]+|[^\s]+|\s+/g) ?? [];
      for (const token of tokens) {
        if (/^curl$/.test(token)) {
          curlExamples.append(makeElement("span", "syntax-command", token));
        } else if (/^--?/.test(token)) {
          curlExamples.append(makeElement("span", "syntax-option", token));
        } else if (/^'.*'$/.test(token)) {
          curlExamples.append(makeElement("span", "syntax-string", token));
        } else {
          curlExamples.append(document.createTextNode(token));
        }
      }
    }
    if (index < lines.length - 1) curlExamples.append(document.createTextNode("\n"));
  }
}

function renderMacroSource(source) {
  const tokenPattern = /\/\/[^\n]*|`(?:\\.|[^`])*`|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|\b(?:async|await|catch|const|else|function|if|new|return|throw|try)\b|\b(?:xapi|JSON|Error|Number|Promise)\b|\b\d+\b/g;
  const tokenClass = (token) => {
    if (token.startsWith("//")) return "syntax-js-comment";
    if (/^[`'"]/.test(token)) return "syntax-js-string";
    if (/^(async|await|catch|const|else|function|if|new|return|throw|try)$/.test(token)) return "syntax-js-keyword";
    if (/^(xapi|JSON|Error|Number|Promise)$/.test(token)) return "syntax-js-api";
    return "syntax-js-number";
  };

  macroCode.replaceChildren();
  let lastIndex = 0;
  for (const match of source.matchAll(tokenPattern)) {
    if (match.index > lastIndex) macroCode.append(document.createTextNode(source.slice(lastIndex, match.index)));
    macroCode.append(makeElement("span", tokenClass(match[0]), match[0]));
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < source.length) macroCode.append(document.createTextNode(source.slice(lastIndex)));
}

function getIconFolderUrl(icon) {
  const repositoryUrl = repository?.url ?? "https://github.com/ctg-tme/Custom-RoomOS-Panel-Icons";
  return new URL("./", new URL(icon.svg, `${repositoryUrl}/tree/main/`)).href;
}

function openIconPreview(icon) {
  dialogTitle.textContent = icon.name;
  dialogImage.src = new URL(icon.svg, siteBase).href;
  dialogImage.alt = `${icon.name} icon`;
  dialogSlug.textContent = icon.slug;
  dialogFolderLink.href = getIconFolderUrl(icon);
  dialogFolderLink.setAttribute("aria-label", `View ${icon.name} files on GitHub (opens in a new tab)`);
  iconDialog.showModal();
}

iconDialog.addEventListener("click", (event) => {
  if (event.target !== iconDialog) return;
  const bounds = iconDialog.getBoundingClientRect();
  if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) {
    iconDialog.close();
  }
});

function render() {
  const query = search.value.trim().toLowerCase();
  const filtered = icons.filter((icon) => `${icon.name} ${icon.slug}`.toLowerCase().includes(query));
  iconGrid.replaceChildren();
  if (filtered.length === 0) {
    iconGrid.append(makeElement("p", "empty-state", icons.length ? "No icons match your search." : "The manifest does not contain any icons."));
    return;
  }
  for (const icon of filtered) {
    const card = makeElement("article", "icon-card");
    const preview = makeElement("button", "icon-preview");
    preview.type = "button";
    preview.setAttribute("aria-label", `Preview ${icon.name}`);
    preview.setAttribute("aria-haspopup", "dialog");
    preview.setAttribute("aria-controls", "icon-dialog");
    preview.addEventListener("click", () => openIconPreview(icon));
    const image = makeElement("img");
    image.src = new URL(icon.svg, siteBase).href;
    image.alt = `${icon.name} icon`;
    image.loading = "lazy";
    preview.append(image);
    const content = makeElement("div", "icon-content");
    const caption = makeElement("div", "icon-caption");
    caption.append(makeElement("h3", "", icon.name));
    caption.append(makeElement("code", "icon-slug", icon.slug));
    const folderLink = makeElement("a", "icon-button icon-folder-link");
    folderLink.href = getIconFolderUrl(icon);
    folderLink.target = "_blank";
    folderLink.rel = "noopener noreferrer";
    folderLink.title = `View ${icon.name} files on GitHub (opens in a new tab)`;
    folderLink.setAttribute("aria-label", folderLink.title);
    folderLink.append(folderLinkIcon.content.cloneNode(true));
    content.append(caption, folderLink);
    card.append(preview, content);
    iconGrid.append(card);
  }
  status.textContent = `${filtered.length} of ${icons.length} icons`;
}

search.addEventListener("input", render);

copyMacro.addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText(macroSource);
    copyStatus.textContent = "Macro functions copied.";
  } catch {
    copyStatus.textContent = "Copy was blocked by the browser. Select and copy the code above.";
  }
});

fetch(new URL("manifest.json", siteBase))
  .then((response) => {
    if (!response.ok) throw new Error(`Manifest request failed (${response.status})`);
    return response.json();
  })
  .then((manifest) => {
    if (!manifest || !Array.isArray(manifest.icons)) throw new Error("Manifest must contain an icons array");
    icons = manifest.icons;
    count.textContent = `${icons.length} icons`;
    render();
  })
  .catch((error) => {
    count.textContent = "Manifest unavailable";
    status.textContent = error.message;
    iconGrid.replaceChildren(makeElement("p", "error-state", "Could not load manifest.json. Check that the file is deployed beside this page."));
  });

Promise.all([
  fetch(new URL("macro-functions.js", siteBase)).then((response) => {
    if (!response.ok) throw new Error(`Macro code request failed (${response.status})`);
    return response.text();
  }),
])
  .then(([source]) => {
    const siteUrl = repository?.siteUrl ?? "https://ctg-tme.github.io/Custom-RoomOS-Panel-Icons/";
    const rawBase = repository?.rawBase ?? "https://raw.githubusercontent.com/ctg-tme/Custom-RoomOS-Panel-Icons/main/";
    macroSource = source.replace("https://ctg-tme.github.io/Custom-RoomOS-Panel-Icons/", siteUrl);
    renderMacroSource(macroSource);
    renderCurlExamples(rawBase);
    copyMacro.disabled = false;
  })
  .catch((error) => {
    macroCode.textContent = error.message;
    curlExamples.textContent = error.message;
  });
